export default function(t,e,a,r){let o={getPlaceholderDays(){var e=[],a=moment().startOf("day");for(let t=30;1<=t;t--)e.push({date:a.clone().subtract(t,"days"),y:Math.floor(16*Math.random())+5});return e},formatXTick(t,e,a){var r=Math.floor(a.length/7);if(!(1<=r&&(a.length-e-1)%r!=0))return moment(t).format(o.getXAxisFormat(a))},getXAxisFormat(t){return!t.length||moment(t[0].value??t[0]).year()===moment(t.at(-1).value??t.at(-1)).year()?"MMM D":"MMM D YYYY"}};return o}